contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address a, address b) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(a != b);
        uint balCA = c.balances(a); if (__ESBMC_reverted()) return;
        uint balCB = c.balances(b); if (__ESBMC_reverted()) return;
        uint totalBefore = address(c).balance + address(this).balance;
        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(!reverted && c.balances(a) == balCA && c.balances(b) == balCB && c.balances(address(this)) == 0 && address(c).balance + address(this).balance == totalBefore);
    }
    receive() external payable {}
}

