// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    keepMyEther c;

    function setUp() public {
        c = new keepMyEther();
    }

    function _run(address a, address b) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(a != b);
        uint256 balCA;
        try c.balances(a) returns (uint256 __r) { balCA = __r; } catch { return; }
        uint256 balCB;
        try c.balances(b) returns (uint256 __r) { balCB = __r; } catch { return; }
        uint totalBefore = address(c).balance + address(this).balance;
        bool reverted;
        try c.withdraw() { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted && c.balances(a) == balCA && c.balances(b) == balCB && c.balances(address(this)) == 0 && address(c).balance + address(this).balance == totalBefore);
    }

    function testFuzz_run(address a, address b) public {
        vm.assume(a.code.length == 0 && uint160(a) > 0xffff && a != address(this) && a != address(c) && a != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && a != 0x000000000000000000636F6e736F6c652e6c6f67 && a != 0x4e59b44847b379578588920cA78FbF26c0B4956C && a != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        vm.assume(b.code.length == 0 && uint160(b) > 0xffff && b != address(this) && b != address(c) && b != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && b != 0x000000000000000000636F6e736F6c652e6c6f67 && b != 0x4e59b44847b379578588920cA78FbF26c0B4956C && b != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(a, b);
    }

    receive() external payable {}
}
